<?php require 'includes/auth.php';if(logged_in())redirect(dashboard_path(current_user()['role']));$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(post('email'));$password=$_POST['password']??'';$s=db()->prepare('SELECT user_id,name,email,password_hash,role,status FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if($u && $u['status']==='active' && password_verify($password,$u['password_hash'])){session_regenerate_id(true);unset($u['password_hash']);$_SESSION['user']=$u;redirect(dashboard_path($u['role']));}$error='Invalid email/password, or this account is not active.';}$pageTitle='Login';require 'includes/header.php';?><div class="container py-5"><div class="row justify-content-center"><div class="col-md-6 col-lg-5"><div class="card"><div class="card-body p-4 p-md-5"><h2>Welcome back</h2><p class="text-muted">Log in to your Myanmar Horizons account.</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post" class="needs-validation" novalidate><?=csrf_field()?><div class="mb-3"><label class="form-label">Email</label><input type="email" name="email" class="form-control" required></div><div class="mb-3"><label class="form-label">Password</label><input type="password" name="password" class="form-control" required></div><button class="btn btn-primary w-100">Log in</button></form><p class="mt-3 mb-0">New traveler? <a href="<?=url('register.php')?>">Create an account</a></p></div></div></div></div></div><?php require 'includes/footer.php'; ?>
